describe('HoleRuntime movers', () => {
  it('gives every moving obstacle type a kinematic body', () => {
    const rig = createRig();
    expect(rig.runtime.moverCount).toBe(obstacles.length);
    rig.dispose();
  });

  it('swings a pendulum along an arc bounded by its swing angle', () => {
    const rig = createRig();
    const samples = rig.sample('clock-pendulum', 6);
    const pivotY = PENDULUM_BASE.y + ARM_LENGTH;

    let maxArc = 0;
    for (const sample of samples) {
      // Arm angle seen from the pivot; 0 means hanging straight down.
      const arc = Math.atan2(sample.x - PENDULUM_BASE.x, pivotY - sample.y);
      expect(Math.abs(arc)).toBeLessThanOrEqual(SWING_ANGLE + 1e-6);
      expect(Math.hypot(sample.x - PENDULUM_BASE.x, sample.y - pivotY)).toBeCloseTo(ARM_LENGTH, 5);
      // The body rotation has to match where the arm sits on the arc.
      expect(sample.angle).toBeCloseTo(arc, 5);
      maxArc = Math.max(maxArc, Math.abs(arc));
    }

    expect(maxArc).toBeGreaterThan(SWING_ANGLE * 0.95);
    expect(samples.some((sample) => sample.x > PENDULUM_BASE.x + 0.1)).toBe(true);
    expect(samples.some((sample) => sample.x < PENDULUM_BASE.x - 0.1)).toBe(true);
    rig.dispose();
  });

  it('ping-pongs a door between its ends and holds during the pause', () => {
    const rig = createRig();
    const xs = rig.sample('cellar-door', 6).map((sample) => sample.x);

    expect(Math.min(...xs)).toBeCloseTo(DOOR_BASE.x, 3);
    expect(Math.max(...xs)).toBeCloseTo(DOOR_BASE.x + DOOR_TRAVEL, 3);
    expect(Math.min(...xs)).toBeGreaterThanOrEqual(DOOR_BASE.x - 1e-6);
    expect(Math.max(...xs)).toBeLessThanOrEqual(DOOR_BASE.x + DOOR_TRAVEL + 1e-6);
    // The door travels back the way it came instead of snapping to the start.
    expect(xs.some((x, index) => index > 0 && x < xs[index - 1]! - 1e-9)).toBe(true);

    let held = 0;
    for (let index = 1; index < xs.length; index += 1) {
      const atEnd = Math.abs(xs[index]! - (DOOR_BASE.x + DOOR_TRAVEL)) < 1e-6;
      if (atEnd && Math.abs(xs[index]! - xs[index - 1]!) < 1e-9) held += 1;
    }
    // 0.5 s of pause at the open end, minus the step that arrives there.
    expect(held).toBeGreaterThanOrEqual(25);
    rig.dispose();
  });

  it('loops a sliding wall back to its origin and keeps the mesh in sync', () => {
    const rig = createRig();
    const xs = rig.sample('sliding-shelf', 5).map((sample) => sample.x);

    expect(Math.max(...xs)).toBeGreaterThan(SHELF_BASE.x + SHELF_TRAVEL * 0.9);
    expect(Math.max(...xs)).toBeLessThanOrEqual(SHELF_BASE.x + SHELF_TRAVEL + 1e-6);
    // A looping mover jumps back to the start instead of walking backwards.
    const deltas = xs.slice(1).map((x, index) => x - xs[index]!);
    expect(deltas.filter((delta) => delta < -1).length).toBe(1);
    expect(deltas.filter((delta) => delta < 0 && delta > -1).length).toBe(0);

    const mesh = rig.runtime.group.getObjectByName('sliding-shelf');
    expect(mesh).toBeDefined();
    expect(mesh!.position.x).toBeCloseTo(xs[xs.length - 1]!, 5);
    rig.dispose();
  });
});
